(g_{1} g_{2}) \triangleleft h = \bigl(g_{1} \triangleleft (g_{2} \triangleright h)\bigl)(g_{2}
\triangleleft h)
\end{equation}
for all $h$, $h_{1}$, $h_{2} \in H$ and $g$, $g_{1}$, $g_{2} \in
G$ (see \cite{Takeuchi}).

